async function main() {
  console.log('Connecting to AAP server...');

  const client = new AAPClient({
    serverUrl: 'ws://localhost:3000/aap'
  });

  try {
    console.log('Starting verification...');
    const result = await client.verify(createSolver());

    console.log('Verification completed successfully!');
    console.log('Public ID:', result.publicId);
    console.log('Session Token:', result.sessionToken);

    // Write summary file
    const summary = `AAP Attestation Summary
========================
Date: ${new Date().toISOString()}
Status: ${result.verified ? 'VERIFIED' : 'FAILED'}
Public ID: ${result.publicId}
Session Token: ${result.sessionToken}
